<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { buscarTitular, listarConexiones, registrarConexion, type ConexionPayload, type ConexionSici, type Option } from '../services/conexiones'

const rows=ref<ConexionSici[]>([]),distritos=ref<Option[]>([]),modalidades=ref<Option[]>([]),loading=ref(false),saving=ref(false),searching=ref(false),modal=ref(false),error=ref(''),success=ref(''),total=ref(0),lastPage=ref(1),titularFound=ref(false)
const filters=reactive({criterio:'',distrito_id:'',servicio:'',page:1})
const empty=():ConexionPayload=>({dni:'',apellido_paterno:'',apellido_materno:'',nombres:'',distrito_id:0,procedencia_id:0,tipo_servicio:'a',inscripcion:'',direccion:'',fecha_solicitud:'',fecha_factibilidad:'',fecha_pago:'',fecha_contrato:'',fecha_instalacion:'',expediente:'',contrato:'',autorizacion_municipal:''})
const form=reactive<ConexionPayload>(empty())
const services:Record<string,string>={a:'Agua',ad:'Agua y alcantarillado',d:'Alcantarillado'}
const dateSteps=computed(()=>[form.fecha_solicitud,form.fecha_factibilidad,form.fecha_pago,form.fecha_contrato,form.fecha_instalacion])
async function load(page=1){loading.value=true;error.value='';filters.page=page;try{const r=await listarConexiones(filters);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;distritos.value=r.distritos;modalidades.value=r.modalidades}catch(e){error.value=msg(e)}finally{loading.value=false}}
function open(){Object.assign(form,empty());titularFound.value=false;error.value='';modal.value=true}
async function findPerson(){if(!/^\d{8}$/.test(form.dni)){error.value='El DNI debe contener exactamente 8 dígitos.';return}searching.value=true;error.value='';try{const person=await buscarTitular(form.dni);titularFound.value=!!person;if(person)Object.assign(form,{titular_id:person.id,apellido_paterno:person.apellido_paterno,apellido_materno:person.apellido_materno,nombres:person.nombres})}catch(e){error.value=msg(e)}finally{searching.value=false}}
function validate(){if(!/^\d{8}$/.test(form.dni))return 'Ingrese un DNI válido de 8 dígitos.';if(!form.apellido_paterno||!form.apellido_materno||!form.nombres)return 'Complete los datos del titular.';if(!form.distrito_id||!form.procedencia_id||!form.inscripcion||form.direccion.length<10)return 'Complete los datos catastrales obligatorios.';const dates=dateSteps.value;if(dates.some(x=>!x))return 'Complete todas las fechas del proceso.';for(let i=1;i<dates.length;i++){const previous=dates[i-1],current=dates[i];if(previous&&current&&current<previous)return 'Las fechas deben respetar el orden solicitud, factibilidad, pago, contrato e instalación.'}if(!/^\d+$/.test(form.expediente)||!/^\d+$/.test(form.contrato))return 'Expediente y contrato deben ser numéricos.';return ''}
async function submit(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;error.value='';try{await registrarConexion({...form});success.value='Conexión SICI registrada correctamente.';modal.value=false;await load(1)}catch(e){error.value=msg(e)}finally{saving.value=false}}
function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / SICI / Conexiones</nav><header class="hero"><div class="mark">04</div><div><small>EVAN · SICI · SUNASS</small><h1>Conexiones del Anexo 04</h1><p>Registro y seguimiento de nuevas conexiones de agua y alcantarillado.</p></div><div class="counter"><b>{{total}}</b><span>conexiones registradas</span></div><button @click="open">+ Nueva conexión</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="DNI, inscripción o titular" @keyup.enter="load(1)"></label><label>Distrito<select v-model="filters.distrito_id"><option value="">Todos</option><option v-for="x in distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Servicio<select v-model="filters.servicio"><option value="">Todos</option><option v-for="(name,key) in services" :key="key" :value="key">{{name}}</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando conexiones…</div><div v-else-if="!rows.length" class="empty">No se encontraron conexiones SICI.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><span>{{x.distrito}}</span><b>{{x.inscripcion}}</b></header><h2>{{x.titular}}</h2><small>DNI {{x.dni}}</small><p>{{x.direccion}}</p><dl><div><dt>Servicio</dt><dd>{{services[x.tipo_servicio]||x.tipo_servicio}}</dd></div><div><dt>Modalidad</dt><dd>{{x.modalidad}}</dd></div><div><dt>Instalación</dt><dd>{{x.fecha_instalacion||'Pendiente'}}</dd></div></dl></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="submit"><header><div><small>ANEXO 04 · SUNASS</small><h2>Registrar nueva conexión</h2></div><button type="button" @click="modal=false">×</button></header><fieldset><legend>1. Titular</legend><div class="dni"><label>DNI *<input v-model.trim="form.dni" maxlength="8" inputmode="numeric" :readonly="titularFound"></label><button type="button" :disabled="searching" @click="findPerson">{{searching?'Buscando…':'Buscar titular'}}</button><em v-if="titularFound">Titular encontrado</em></div><div class="grid three"><label>Apellido paterno *<input v-model.trim="form.apellido_paterno" :readonly="titularFound"></label><label>Apellido materno *<input v-model.trim="form.apellido_materno" :readonly="titularFound"></label><label>Nombres *<input v-model.trim="form.nombres" :readonly="titularFound"></label></div></fieldset><fieldset><legend>2. Datos de la conexión</legend><div class="grid three"><label>Distrito *<select v-model.number="form.distrito_id"><option :value="0">Seleccione</option><option v-for="x in distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Modalidad de ejecución *<select v-model.number="form.procedencia_id"><option :value="0">Seleccione</option><option v-for="x in modalidades" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de servicio *<select v-model="form.tipo_servicio"><option v-for="(name,key) in services" :key="key" :value="key">{{name}}</option></select></label><label>Código de inscripción *<input v-model.trim="form.inscripcion" maxlength="8"></label><label class="span2">Dirección *<input v-model.trim="form.direccion"></label></div></fieldset><fieldset><legend>3. Documentación y fechas</legend><div class="timeline"><label>Solicitud *<input v-model="form.fecha_solicitud" type="date"></label><label>Factibilidad *<input v-model="form.fecha_factibilidad" type="date"></label><label>Pago *<input v-model="form.fecha_pago" type="date"></label><label>Contrato *<input v-model="form.fecha_contrato" type="date"></label><label>Instalación *<input v-model="form.fecha_instalacion" type="date"></label></div><div class="grid three"><label>N.° de expediente *<input v-model.trim="form.expediente" inputmode="numeric"></label><label>N.° de contrato *<input v-model.trim="form.contrato" inputmode="numeric"></label><label>Autorización municipal<input v-model.trim="form.autorizacion_municipal"></label></div></fieldset><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar conexión'}}</button></footer></form></div></div></template>

<style scoped>
