}.modal{width:min(100%,920px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex;align-items:start}.modal>header h2{margin:2px 0;font-size:1rem}.modal>header button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal fieldset{margin:14px 0;padding:13px;border:1px solid #e0e7e9;border-radius:7px}.modal legend{padding:0 5px;color:var(--a);font-size:.57rem;font-weight:700}.modal label{font-size:.48rem}.grid{display:grid;gap:8px}.three{grid-template-columns:repeat(3,1fr)}.span2{grid-column:span 2}.dni{display:grid;grid-template-columns:2fr auto 1fr;align-items:end;gap:8px;margin-bottom:9px}.dni em{padding:8px;color:#26745a;background:#eaf8f1;font-size:.48rem;font-style:normal}.timeline{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-bottom:9px}.modal footer{display:flex;justify-content:flex-end;gap:7px}.clear{color:#637179!important;background:#edf1f2!important}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}.timeline{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.hero{flex-wrap:wrap}.counter{margin-left:0}.filters{align-items:stretch;flex-direction:column}.filters label{width:100%}.cards,.three,.timeline,.dni{grid-template-columns:1fr}.span2{grid-column:auto}}
